nextflow_process {

    name "Test Process ANTISMASH_ANTISMASH"
    script "../main.nf"
    process "ANTISMASH_ANTISMASH"
    config './nextflow.config'

    tag "modules"
    tag "modules_nfcore"
    tag "antismash"
    tag "antismash/antismash"
    tag "antismash/antismashdownloaddatabases"
    tag "gunzip"


    setup {
        run("ANTISMASH_ANTISMASHDOWNLOADDATABASES") {
            script "../../../antismash/antismashdownloaddatabases"
            process {
                """
                """
            }
        }

        run("GUNZIP") {
            script "../../../gunzip"
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/prokaryotes/bacteroides_fragilis/genome/genome.gbff.gz', checkIfExists: true)
                ]
                """
            }
        }
    }

    test("antismash - bacteroides_fragilis - genome") {

        when {
            process {
                """
                input[0] = GUNZIP.out.gunzip
                input[1] = ANTISMASH_ANTISMASHDOWNLOADDATABASES.out.database
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert path(process.out.gbk_results.get(0).get(1).get(0)).text.contains("##antiSMASH-Data-START##") },
                { assert path(process.out.gbk_input.get(0).get(1).get(0)).text.contains("##antiSMASH-Data-END##") },
                { assert path(process.out.html.get(0).get(1)).text.contains("https://antismash.secondarymetabolites.org/") },
                { assert path(process.out.json_sideloading.get(0).get(1)).text.contains("NZ_CP069563.1") },
                { assert path(process.out.log.get(0).get(1)).text.contains("antiSMASH status: SUCCESS") },
                { assert snapshot(
                    file(process.out.zip.get(0).get(1)).name,
                    process.out.html_accessory_files,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match()}
            )
        }
    }

    test("antismash - bacteroides_fragilis - genome - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = GUNZIP.out.gunzip
                input[1] = ANTISMASH_ANTISMASHDOWNLOADDATABASES.out.database
                input[2] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match()}
            )
        }
    }
}
